1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"time"
11	)
12	
13	// 数据目录布局：
14	//
15	//	<dir>/state.json      全部业务数据（客户、用量、账单、封账状态）
16	//	<dir>/state.json.tmp  原子写入临时文件（保存后 rename 覆盖）
17	//
18	// 所有命令顺序运行，单次调用内完成“读入—修改—整体原子落盘”，
19	// 因此账单与封账状态在同一次保存中持久化，不会出现半写状态。
20	
21	const stateVersion = 1
22	
23	type customer struct {
24		ID    string `json:"id"`
25		Name  string `json:"name"`
26		Price int64  `json:"price_fen"` // 固定单价，非负整数分，创建后不可修改
27	}
28	
29	type usageRecord struct {
30		ID         string `json:"id"`
31		CustomerID string `json:"customer_id"`
32		Time       string `json:"time"` // RFC3339，保留原始输入用于去重判定
33		Quantity   int64  `json:"quantity"`
34	}
35	
36	type billLine struct {
37		UsageID  string `json:"usage_id"`
38		Time     string `json:"time"`
39		Quantity int64  `json:"quantity"`
40		LineFee  int64  `json:"line_fee_fen"`
41	}
42	
43	type bill struct {
44		ID         string     `json:"id"`
45		CustomerID string     `json:"customer_id"`
46		Month      string     `json:"month"` // YYYY-MM（UTC）
47		TotalQty   int64      `json:"total_quantity"`
48		UnitPrice  int64      `json:"unit_price_fen"`
49		TotalFee   int64      `json:"total_fee_fen"`
50		Lines      []billLine `json:"lines"`
51		CreatedAt  string     `json:"created_at"`
52	}
53	
54	type state struct {
55		Version   int                     `json:"version"`
56		Customers map[string]*customer    `json:"customers"`
57		Usage     map[string]*usageRecord `json:"usage"` // 全局唯一用量标识 -> 记录
58		Bills     map[string]*bill        `json:"bills"` // 客户 + "|" + 月份 -> 账单
59		path      string                  `json:"-"`
60	}
61	
62	// loadStore 读取数据目录；目录不存在时按需创建并视为空库。
63	// 已存在但损坏或不可读取的数据一律报错，绝不当作空库覆盖。
64	func loadStore(dir string) (*state, error) {
65		p := filepath.Join(dir, "state.json")
66		data, err := os.ReadFile(p)
67		if err != nil {
68			if errors.Is(err, os.ErrNotExist) {
69				if mkErr := os.MkdirAll(dir, 0o755); mkErr != nil {
70					return nil, fmt.Errorf("无法创建数据目录 %s: %w", dir, mkErr)
71				}
72				return newState(p), nil
73			}
74			return nil, fmt.Errorf("数据文件不可读取 %s: %w", p, err)
75		}
76	
77		var s state
78		dec := json.NewDecoder(bytes.NewReader(data))
79		if err := dec.Decode(&s); err != nil {
80			return nil, fmt.Errorf("数据文件已损坏（不是有效的 JSON）%s: %w", p, err)
81		}
82		// 拒绝尾部多余内容，避免静默吞掉异常数据。
83		if dec.More() {
84			return nil, fmt.Errorf("数据文件已损坏（JSON 之后存在多余内容）: %s", p)
85		}
86		if err := s.validate(); err != nil {
87			return nil, fmt.Errorf("数据文件已损坏: %w", err)
88		}
89		s.path = p
90		return &s, nil
91	}
92	
93	func newState(p string) *state {
94		return &state{
95			Version:   stateVersion,
96			Customers: map[string]*customer{},
97			Usage:     map[string]*usageRecord{},
98			Bills:     map[string]*bill{},
99			path:      p,
100		}
101	}
102	
103	// validate 对读入的库做一致性检查，任何异常都按损坏处理。
104	func (s *state) validate() error {
105		if s.Version != stateVersion {
106			return fmt.Errorf("不支持的数据版本 %d（仅支持 %d）", s.Version, stateVersion)
107		}
108		if s.Customers == nil || s.Usage == nil || s.Bills == nil {
109			return errors.New("缺少必要的数据节")
110		}
111		for id, c := range s.Customers {
112			if c == nil {
113				return fmt.Errorf("客户 %q 的数据为空", id)
114			}
115			if c.ID != id {
116				return fmt.Errorf("客户标识不一致: 键 %q / 记录 %q", id, c.ID)
117			}
118			if c.ID == "" || c.Name == "" {
119				return fmt.Errorf("客户 %q 的标识或名称为空", id)
120			}
121			if c.Price < 0 {
122				return fmt.Errorf("客户 %q 单价为负", id)
123			}
124		}
125		for id, u := range s.Usage {
126			if u == nil {
127				return fmt.Errorf("用量 %q 的数据为空", id)
128			}
129			if u.ID != id {
130				return fmt.Errorf("用量标识不一致: 键 %q / 记录 %q", id, u.ID)
131			}
132			if u.ID == "" {
133				return errors.New("存在空的用量标识")
134			}
135			if _, ok := s.Customers[u.CustomerID]; !ok {
136				return fmt.Errorf("用量 %q 引用了不存在的客户 %q", u.ID, u.CustomerID)
137			}
138			if u.Quantity <= 0 {
139				return fmt.Errorf("用量 %q 的数量非正", u.ID)
140			}
141			if _, err := time.Parse(time.RFC3339, u.Time); err != nil {
142				return fmt.Errorf("用量 %q 的时间不是 RFC3339: %w", u.ID, err)
143			}
144		}
145		for key, b := range s.Bills {
146			if b == nil {
147				return fmt.Errorf("账单 %q 的数据为空", key)
148			}
149			if billKey(b.CustomerID, b.Month) != key {
150				return fmt.Errorf("账单键不一致: 键 %q / 客户月份 %s|%s", key, b.CustomerID, b.Month)
151			}
152			if _, ok := s.Customers[b.CustomerID]; !ok {
153				return fmt.Errorf("账单 %q 引用了不存在的客户 %q", key, b.CustomerID)
154			}
155			if !validMonth(b.Month) {
156				return fmt.Errorf("账单 %q 的月份无效", key)
157			}
158			if len(b.Lines) == 0 {
159				return fmt.Errorf("账单 %q 没有明细", key)
160			}
161			var qty, fee int64
162			for _, ln := range b.Lines {
163				u, ok := s.Usage[ln.UsageID]
164				if !ok {
165					return fmt.Errorf("账单 %q 引用了不存在的用量 %q", key, ln.UsageID)
166				}
167				if u.CustomerID != b.CustomerID || u.Time != ln.Time || u.Quantity != ln.Quantity {
168					return fmt.Errorf("账单 %q 的明细 %q 与用量记录不一致", key, ln.UsageID)
169				}
170				if !inMonth(u.Time, b.Month) {
171					return fmt.Errorf("账单 %q 的明细 %q 不在账期内", key, ln.UsageID)
172				}
173				var err error
174				qty, err = add64(qty, ln.Quantity)
175				if err != nil {
176					return fmt.Errorf("账单 %q 汇总数量溢出", key)
177				}
178				fee, err = add64(fee, ln.LineFee)
179				if err != nil {
180					return fmt.Errorf("账单 %q 汇总金额溢出", key)
181				}
182			}
183			if qty != b.TotalQty {
184				return fmt.Errorf("账单 %q 总数量与明细不符", key)
185			}
186			if fee != b.TotalFee {
187				return fmt.Errorf("账单 %q 总金额与明细不符", key)
188			}
189			c := s.Customers[b.CustomerID]
190			for _, ln := range b.Lines {
191				lf, err := mul64(ln.Quantity, c.Price)
192				if err != nil {
193					return fmt.Errorf("账单 %q 明细 %q 小计溢出", key, ln.UsageID)
194				}
195				if lf != ln.LineFee {
196					return fmt.Errorf("账单 %q 明细 %q 小计与数量×单价不符", key, ln.UsageID)
197				}
198			}
199			if b.UnitPrice != c.Price {
200				return fmt.Errorf("账单 %q 单价与客户固定单价不符", key)
201			}
202			// 封账期内不得存在游离于账单之外的用量（封账后新增被禁止，
203			// 而已入账记录理应全部在明细中）。
204			for _, u := range s.Usage {
205				if u.CustomerID == b.CustomerID && inMonth(u.Time, b.Month) {
206					found := false
207					for _, ln := range b.Lines {
208						if ln.UsageID == u.ID {
209							found = true
210							break
211						}
212					}
213					if !found {
214						return fmt.Errorf("客户 %s 的 %s 已封账，但用量 %q 未计入账单", b.CustomerID, b.Month, u.ID)
215					}
216				}
217			}
218		}
219		return nil
220	}
221	
222	// save 整体原子落盘：先写临时文件并同步，再 rename 覆盖。
223	// 只有完整保存成功后调用方才会向用户报告成功。
224	func (s *state) save() error {
225		if err := s.validate(); err != nil {
226			return fmt.Errorf("拒绝写入不一致的数据: %w", err)
227		}
228		data, err := json.MarshalIndent(s, "", "  ")
229		if err != nil {
230			return fmt.Errorf("序列化数据失败: %w", err)
231		}
232		data = append(data, '\n')
233	
234		tmp := s.path + ".tmp"
235		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
236		if err != nil {
237			return fmt.Errorf("写入临时数据文件失败: %w", err)
238		}
239		if _, err := f.Write(data); err != nil {
240			f.Close()
241			os.Remove(tmp)
242			return fmt.Errorf("写入临时数据文件失败: %w", err)
243		}
244		if err := f.Sync(); err != nil {
245			f.Close()
246			os.Remove(tmp)
247			return fmt.Errorf("同步数据文件失败: %w", err)
248		}
249		if err := f.Close(); err != nil {
250			os.Remove(tmp)
251			return fmt.Errorf("关闭数据文件失败: %w", err)
252		}
253		if err := os.Rename(tmp, s.path); err != nil {
254			os.Remove(tmp)
255			return fmt.Errorf("替换数据文件失败: %w", err)
256		}
257		if dir, err := os.Open(filepath.Dir(s.path)); err == nil {
258			dir.Sync()
259			dir.Close()
260		}
261		return nil
262	}
263	
264	func billKey(customerID, month string) string {
265		return customerID + "|" + month
266	}
267	
268	// sealed 报告某客户的指定月份是否已封账。
269	func (s *state) sealed(customerID, month string) bool {
270		_, ok := s.Bills[billKey(customerID, month)]
271		return ok
272	}
