118	func parsePrice(text string) (int64, error) {
119		text = strings.TrimSpace(text)
120		price, err := strconv.ParseInt(text, 10, 64)
121		if err != nil {
122			return 0, fmt.Errorf("单价 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
123		}
124		if price < 0 {
125			return 0, fmt.Errorf("单价必须是非负整数分，收到 %d", price)
126		}
127		return price, nil
128	}
129	
130	// parsedRow 是导入文件中一行解析后的候选用量。
131	type parsedRow struct {
132		line int // 文件中的行号（含表头），用于报错定位
133		rec  usageRecord
134		t    time.Time
135	}
136	
137	func cmdUsageImport(dir, file string) error {
138		var reader io.ReadCloser
139		var source string
140		if file == "-" {
141			reader = io.NopCloser(os.Stdin)
142			source = "标准输入"
143		} else {
144			f, err := os.Open(file)
145			if err != nil {
146				return fmt.Errorf("无法打开用量文件 %s: %w", file, err)
147			}
148			reader = f
149			source = file
150		}
151		defer reader.Close()
152	
153		rows, parseErrs := parseUsageFile(reader)
154	
155		s, err := loadStore(dir)
156		if err != nil {
157			return err
158		}
159	
160		// 先校验：任何问题都在此阶段收集，全部通过后才一次性修改并保存，
161		// 保证“整批导入先校验再生效”，失败不留下任何新用量。
162		var problems []string
163		problems = append(problems, parseErrs...)
164	
165		accepted := make(map[string]*parsedRow) // 本批内首次出现、内容确定的记录
166		var ordered []*parsedRow
167		newCount, dupCount := 0, 0
168	
169		for _, r := range rows {
170			cust, ok := s.Customers[r.rec.CustomerID]
171			if !ok {
172				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识 %q 不存在", r.line, r.rec.CustomerID))
173				continue
174			}
175			// 金额可行性预检：数量×固定单价不得溢出（金额单位：分）。
176			if _, err := mul64(r.rec.Quantity, cust.Price); err != nil {
177				problems = append(problems, fmt.Sprintf("第 %d 行：数量 %d × 单价 %d 金额溢出有符号 64 位整数范围", r.line, r.rec.Quantity, cust.Price))
178				continue
179			}
180	
181			// 去重判定同时对“库中已有”和“本文件内已出现”生效。
182			var existing *usageRecord
183			if inStore, ok := s.Usage[r.rec.ID]; ok {
184				existing = inStore
185			} else if inBatch, ok := accepted[r.rec.ID]; ok {
186				existing = &inBatch.rec
187			}
188	
189			if existing != nil {
190				if !sameUsage(existing, &r.rec, r.t) {
191					problems = append(problems, fmt.Sprintf("第 %d 行：用量标识 %q 已存在但内容不同（已有客户=%s 时间=%s 数量=%d）",
192						r.line, r.rec.ID, existing.CustomerID, existing.Time, existing.Quantity))
193					continue
194				}
195				dupCount++
196				continue
197			}
198	
199			// 全新标识：不得进入该客户已封账的 UTC 自然月。
200			month := r.t.UTC().Format("2006-01")
201			if s.sealed(r.rec.CustomerID, month) {
202				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 已封账，新用量 %q 不得进入",
203					r.line, r.rec.CustomerID, month, r.rec.ID))
204				continue
205			}
206	
207			rr := r
208			accepted[r.rec.ID] = rr
209			ordered = append(ordered, rr)
210			newCount++
211		}
212	
213		if len(problems) > 0 {
214			return fmt.Errorf("导入失败，整批未生效（共 %d 个问题）：\n  %s", len(problems), strings.Join(problems, "\n  "))
215		}
216	
217		for _, r := range ordered {
218			rec := r.rec
219			s.Usage[rec.ID] = &rec
220		}
221		if err := s.save(); err != nil {
222			return err
223		}
224		fmt.Fprintf(stdout, "导入完成（%s）：新增 %d 条，重复跳过 %d 条\n", source, newCount, dupCount)
225		return nil
226	}
