228	// parseUsageFile 完整读取 CSV，做格式层面的解析；业务层面的校验在调用方完成。
229	func parseUsageFile(r io.Reader) ([]*parsedRow, []string) {
230		cr := csv.NewReader(r)
231		cr.FieldsPerRecord = 4
232		cr.TrimLeadingSpace = true
233	
234		header, err := cr.Read()
235		if err == io.EOF {
236			return nil, []string{"文件为空：首行必须是表头 " + usageHeader}
237		}
238		if err != nil {
239			return nil, []string{fmt.Sprintf("无法读取表头：%v（首行必须是 %s）", err, usageHeader)}
240		}
241		for i := range header {
242			header[i] = strings.TrimSpace(header[i])
243		}
244		if len(header) != 4 || header[0] != "usage_id" || header[1] != "customer_id" ||
245			header[2] != "time" || header[3] != "quantity" {
246			return nil, []string{fmt.Sprintf("表头必须是 %s，实际为 %s", usageHeader, strings.Join(header, ","))}
247		}
248	
249		var rows []*parsedRow
250		var problems []string
251		line := 1
252		for {
253			rec, err := cr.Read()
254			if err == io.EOF {
255				break
256			}
257			line++
258			if err != nil {
259				problems = append(problems, fmt.Sprintf("第 %d 行：CSV 格式错误：%v", line, err))
260				if pe, ok := err.(*csv.ParseError); ok && pe.Err == csv.ErrFieldCount {
261					// 字段数错误后继续读取仍可能拿到错乱记录，直接终止解析。
262					break
263				}
264				continue
265			}
266			for i := range rec {
267				rec[i] = strings.TrimSpace(rec[i])
268			}
269	
270			id, custID, ts, qtyText := rec[0], rec[1], rec[2], rec[3]
271			if id == "" {
272				problems = append(problems, fmt.Sprintf("第 %d 行：用量标识不能为空", line))
273				continue
274			}
275			if custID == "" {
276				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识不能为空", line))
277				continue
278			}
279			t, err := time.Parse(time.RFC3339, ts)
280			if err != nil {
281				problems = append(problems, fmt.Sprintf("第 %d 行：时间 %q 不是 RFC3339 格式：%v", line, ts, err))
282				continue
283			}
284			qty, err := strconv.ParseInt(qtyText, 10, 64)
285			if err != nil {
286				problems = append(problems, fmt.Sprintf("第 %d 行：数量 %q 不是有符号 64 位整数", line, qtyText))
287				continue
288			}
289			if qty <= 0 {
290				problems = append(problems, fmt.Sprintf("第 %d 行：数量必须是正整数，收到 %d", line, qty))
291				continue
292			}
293	
294			rows = append(rows, &parsedRow{
295				line: line,
296				rec:  usageRecord{ID: id, CustomerID: custID, Time: ts, Quantity: qty},
297				t:    t,
298			})
299		}
300		return rows, problems
301	}
302	
303	// sameUsage 按（客户、解析后的时间点、数量）判定两条记录内容是否相同，
304	// 时间比较的是瞬间，因此 Z 与 +08:00 表示同一时刻视为相同。
305	func sameUsage(existing *usageRecord, candidate *usageRecord, candidateT time.Time) bool {
306		if existing.CustomerID != candidate.CustomerID || existing.Quantity != candidate.Quantity {
307			return false
308		}
309		et, err := time.Parse(time.RFC3339, existing.Time)
310		if err != nil {
311			return existing.Time == candidate.Time
312		}
313		return et.Equal(candidateT)
314	}
315	
316	// validMonth 严格校验 YYYY-MM（月份两位、01..12）。
317	func validMonth(m string) bool {
318		t, err := time.Parse("2006-01", m)
319		if err != nil || t.Format("2006-01") != m || t.Year() < 1 {
320			return false
321		}
322		return true
323	}
324	
325	// inMonth 判定一条 RFC3339 时间（换算 UTC 后）是否落在给定自然月。
326	func inMonth(rfc3339, month string) bool {
327		t, err := time.Parse(time.RFC3339, rfc3339)
328		if err != nil {
329			return false
330		}
331		return t.UTC().Format("2006-01") == month
332	}
333	
334	func cmdBillSettle(dir, customerID, month string) error {
335		if !validMonth(month) {
336			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
337		}
338		s, err := loadStore(dir)
339		if err != nil {
340			return err
341		}
342		cust, ok := s.Customers[customerID]
343		if !ok {
344			return fmt.Errorf("客户标识 %q 不存在", customerID)
345		}
346	
347		key := billKey(customerID, month)
348		if existing, ok := s.Bills[key]; ok {
349			// 幂等：同一客户同一月份重复结算，直接返回原账单，
350			// 不重新计费、不产生新账单、不落盘。
351			fmt.Fprintf(stdout, "客户 %s 的 %s 已结算，返回原账单（幂等，不重新计费）：\n\n", customerID, month)
352			printBill(existing, cust)
353			return nil
354		}
355	
356		// 归集该客户 UTC 自然月内的全部用量，区间为左闭右开 [月初, 下月初)。
357		var inMonthRecs []*usageRecord
358		for _, u := range s.Usage {
359			if u.CustomerID == customerID && inMonth(u.Time, month) {
360				inMonthRecs = append(inMonthRecs, u)
361			}
362		}
363		if len(inMonthRecs) == 0 {
364			return fmt.Errorf("客户 %s 在 %s 没有用量，拒绝结算且不封账", customerID, month)
365		}
366		sortByInstant(inMonthRecs)
367	
368		lines := make([]billLine, 0, len(inMonthRecs))
369		var totalQty, totalFee int64
370		for _, u := range inMonthRecs {
371			lineFee, err := mul64(u.Quantity, cust.Price)
372			if err != nil {
373				return fmt.Errorf("用量 %s：数量 %d × 单价 %d 金额溢出，拒绝结算且不封账", u.ID, u.Quantity, cust.Price)
374			}
375			totalQty, err = add64(totalQty, u.Quantity)
376			if err != nil {
377				return fmt.Errorf("汇总数量溢出有符号 64 位整数范围，拒绝结算且不封账")
378			}
379			totalFee, err = add64(totalFee, lineFee)
380			if err != nil {
381				return fmt.Errorf("汇总金额溢出有符号 64 位整数范围，拒绝结算且不封账")
382			}
383			lines = append(lines, billLine{
384				UsageID:  u.ID,
385				Time:     u.Time,
386				Quantity: u.Quantity,
387				LineFee:  lineFee,
388			})
389		}
390	
391		b := &bill{
392			ID:         stableBillID(customerID, month),
393			CustomerID: customerID,
