1	package main
2	
3	import (
4		"bytes"
5		"errors"
6		"os"
7		"path/filepath"
8		"strings"
9		"testing"
10	)
11	
12	// 每个用例使用独立临时数据目录，每次调用 run 都重新从磁盘载入，
13	// 天然模拟“跨进程”持久化。
14	
15	type harness struct {
16		t   *testing.T
17		dir string
18		buf bytes.Buffer
19	}
20	
21	func newHarness(t *testing.T) *harness {
22		t.Helper()
23		h := &harness{t: t, dir: t.TempDir()}
24		prev := stdout
25		stdout = &h.buf
26		t.Cleanup(func() { stdout = prev })
27		return h
28	}
