```go
func addSigned64(a, b int64) (int64, error) {
    if b > 0 && a > math.MaxInt64-b { return 0, errOverflow }
    if b < 0 && a < math.MinInt64-b { return 0, errOverflow }
    return a + b, nil
}
```
