```go
func sumAdjustments(adjs []*adjustment) (net int64, err error) {
    var pos, neg int64
    for _, a := range adjs {
        if a.Revoked { continue }
        if a.Amount > 0 {
            pos, err = add64(pos, a.Amount) // both non-negative
            if err != nil { return 0, err }
        } else {
            neg, err = addSigned64(neg, a.Amount)
            if err != nil { return 0, err }
        }
    }
    // total = pos + neg, both bounded; pos+neg can't overflow since pos ≤ MaxInt64, neg ≥ MinInt64 → sum in [MinInt64, MaxInt64]? pos+neg where pos≥0, neg≤0: max is pos ≤ MaxInt64, min is neg ≥ MinInt64. No overflow.
    return pos + neg, nil
}

func currentPayable(b *bill, adjs []*adjustment) (int64, error) {
    net, err := sumAdjustments(adjs)
    if err != nil { return 0, err }
    pay, err := addSigned64(b.TotalFee, net)
    if err != nil { return 0, err }
    if pay < 0 { return 0, fmt.Errorf("当前应付 %d 分小于 0", pay) }
    return pay, nil
}
```

