```go
func cmdBillRevoke(dir, adjID, reason string) error {
    if strings.TrimSpace(adjID) == "" {
        return fmt.Errorf("调整标识不能为空")
    }
    if strings.TrimSpace(reason) == "" {
        return fmt.Errorf("撤销原因不能为空")
    }
    s, err := loadStore(dir)
    if err != nil { return err }
    adj, ok := s.Adjustments[adjID]
    if !ok {
        return fmt.Errorf("撤销目标不存在：调整标识 %q 没有记录", adjID)
    }
    if adj.Revoked {
        if adj.RevokeReason == reason {
            fmt.Fprintf(stdout, "调整 %q 已撤销且撤销原因相同，返回原记录（幂等，不新增记录）：\n\n", adjID)
            printAdjustment(adj)
            return nil
        }
        return fmt.Errorf("调整 %q 已撤销（撤销原因 %q），改用其他原因 %q 重复撤销被拒绝", adjID, adj.RevokeReason, reason)
    }
    b := s.Bills[billKey(adj.CustomerID, adj.Month)] // validate 保证存在
    adjs := adjustmentsFor(s, adj.CustomerID, adj.Month)
    // 模拟撤销后的应付：排除本笔
    var others []*adjustment
    for _, a := range adjs { if a.ID != adjID { others = append(others, a) } }
    pay, err := currentPayable(b, others)
    if err != nil {
        return fmt.Errorf("撤销后当前应付将越界（须介于 0 与 %d 之间），拒绝撤销，该调整仍有效: %w", math.MaxInt64, err)
    }
    s.NextSeq++
    adj.Revoked = true
    adj.RevokeReason = reason
    adj.RevokeSeq = s.NextSeq
    adj.RevokedAt = time.Now().UTC().Format(time.RFC3339)
    if err := s.save(); err != nil {
        adj.Revoked = false
        adj.RevokeReason = ""
        adj.RevokeSeq = 0
        adj.RevokedAt = ""
        s.NextSeq--
        return err
    }
    fmt.Fprintf(stdout, "已撤销调整 %q（账单 %s，原因 %q）：仅取消该笔金额影响，当前应付 %d 分（%s）\n", adjID, b.ID, reason, pay, moneyFen(pay))
    return nil
}
