func currentPayable(b *bill, adjs []*adjustment) (int64, error) {
	net, err := netAdjustments(adjs)
	if err != nil {
		return 0, err
	}
	pay, err := addSigned64(b.TotalFee, net)
	if err != nil {
		return 0, err
	}
	if pay < 0 {
		return 0, fmt.Errorf("当前应付 %d 分小于 0", pay)
	}
	return pay, nil
}

