1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"time"
12	)
13	
14	// 数据目录布局：
15	//
16	//	<dir>/state.json      全部业务数据（客户、用量、账单、封账状态）
17	//	<dir>/state.json.tmp  原子写入临时文件（保存后 rename 覆盖）
18	//
19	// 所有命令顺序运行，单次调用内完成“读入—修改—整体原子落盘”，
20	// 因此账单与封账状态在同一次保存中持久化，不会出现半写状态。
21	
22	const stateVersion = 1
23	
24	type customer struct {
25		ID    string `json:"id"`
26		Name  string `json:"name"`
27		Price int64  `json:"price_fen"` // 固定单价，非负整数分，创建后不可修改
28	}
29	
30	type usageRecord struct {
31		ID         string `json:"id"`
32		CustomerID string `json:"customer_id"`
33		Time       string `json:"time"` // RFC3339，保留原始输入用于去重判定
34		Quantity   int64  `json:"quantity"`
35	}
36	
37	type billLine struct {
38		UsageID  string `json:"usage_id"`
39		Time     string `json:"time"`
40		Quantity int64  `json:"quantity"`
41		LineFee  int64  `json:"line_fee_fen"`
42	}
43	
44	type bill struct {
45		ID         string     `json:"id"`
46		CustomerID string     `json:"customer_id"`
47		Month      string     `json:"month"` // YYYY-MM（UTC）
48		TotalQty   int64      `json:"total_quantity"`
49		UnitPrice  int64      `json:"unit_price_fen"`
50		TotalFee   int64      `json:"total_fee_fen"`
51		Lines      []billLine `json:"lines"`
52		CreatedAt  string     `json:"created_at"`
53	}
54	
55	// adjustment 是作用于已结算账单的一笔费用调整：
56	// 正数金额为补收，负数为减免。撤销只取消金额影响，记录永久保留。
57	type adjustment struct {
58		ID           string `json:"id"`          // 全局唯一调整标识，非空
59		CustomerID   string `json:"customer_id"` // 所属账单的客户与月份
60		Month        string `json:"month"`
61		Amount       int64  `json:"amount_fen"` // 非零；正补收、负减免
62		Reason       string `json:"reason"`     // 非空
63		Seq          int64  `json:"seq"`        // 成功操作顺序号（全局递增）
64		CreatedAt    string `json:"created_at"`
65		Revoked      bool   `json:"revoked"`
66		RevokeReason string `json:"revoke_reason,omitempty"` // 撤销时必填
67		RevokeSeq    int64  `json:"revoke_seq,omitempty"`
68		RevokedAt    string `json:"revoked_at,omitempty"`
69	}
70	
71	type state struct {
72		Version     int                     `json:"version"`
73		Customers   map[string]*customer    `json:"customers"`
74		Usage       map[string]*usageRecord `json:"usage"`       // 全局唯一用量标识 -> 记录
75		Bills       map[string]*bill        `json:"bills"`       // 客户 + "|" + 月份 -> 账单
76		Adjustments map[string]*adjustment  `json:"adjustments"` // 全局唯一调整标识 -> 记录
77		NextSeq     int64                   `json:"next_seq"`    // 已发放的最大操作顺序号
78		path        string                  `json:"-"`
79	}
