81	// loadStore 读取数据目录；目录不存在时按需创建并视为空库。
82	// 已存在但损坏或不可读取的数据一律报错，绝不当作空库覆盖。
83	func loadStore(dir string) (*state, error) {
84		p := filepath.Join(dir, "state.json")
85		data, err := os.ReadFile(p)
86		if err != nil {
87			if errors.Is(err, os.ErrNotExist) {
88				if mkErr := os.MkdirAll(dir, 0o755); mkErr != nil {
89					return nil, fmt.Errorf("无法创建数据目录 %s: %w", dir, mkErr)
90				}
91				return newState(p), nil
92			}
93			return nil, fmt.Errorf("数据文件不可读取 %s: %w", p, err)
94		}
95	
96		var s state
97		dec := json.NewDecoder(bytes.NewReader(data))
98		if err := dec.Decode(&s); err != nil {
99			return nil, fmt.Errorf("数据文件已损坏（不是有效的 JSON）%s: %w", p, err)
100		}
101		// 拒绝尾部多余内容，避免静默吞掉异常数据。
102		if dec.More() {
103			return nil, fmt.Errorf("数据文件已损坏（JSON 之后存在多余内容）: %s", p)
104		}
105		// 旧数据文件可能不含调整相关字段：视为零调整，顺序号从零开始。
106		if s.Adjustments == nil {
107			s.Adjustments = map[string]*adjustment{}
108		}
109		if err := s.validate(); err != nil {
110			return nil, fmt.Errorf("数据文件已损坏: %w", err)
111		}
112		s.path = p
113		return &s, nil
114	}
