116	func newState(p string) *state {
117		return &state{
118			Version:     stateVersion,
119			Customers:   map[string]*customer{},
120			Usage:       map[string]*usageRecord{},
121			Bills:       map[string]*bill{},
122			Adjustments: map[string]*adjustment{},
123			path:        p,
124		}
125	}
