127	// validate 对读入的库做一致性检查，任何异常都按损坏处理。
128	func (s *state) validate() error {
129		if s.Version != stateVersion {
130			return fmt.Errorf("不支持的数据版本 %d（仅支持 %d）", s.Version, stateVersion)
131		}
132		if s.Customers == nil || s.Usage == nil || s.Bills == nil {
133			return errors.New("缺少必要的数据节")
134		}
135		for id, c := range s.Customers {
136			if c == nil {
137				return fmt.Errorf("客户 %q 的数据为空", id)
138			}
139			if c.ID != id {
140				return fmt.Errorf("客户标识不一致: 键 %q / 记录 %q", id, c.ID)
141			}
142			if c.ID == "" || c.Name == "" {
143				return fmt.Errorf("客户 %q 的标识或名称为空", id)
144			}
145			if c.Price < 0 {
146				return fmt.Errorf("客户 %q 单价为负", id)
147			}
148		}
149		for id, u := range s.Usage {
150			if u == nil {
151				return fmt.Errorf("用量 %q 的数据为空", id)
152			}
153			if u.ID != id {
154				return fmt.Errorf("用量标识不一致: 键 %q / 记录 %q", id, u.ID)
155			}
156			if u.ID == "" {
157				return errors.New("存在空的用量标识")
158			}
159			if _, ok := s.Customers[u.CustomerID]; !ok {
160				return fmt.Errorf("用量 %q 引用了不存在的客户 %q", u.ID, u.CustomerID)
161			}
162			if u.Quantity <= 0 {
163				return fmt.Errorf("用量 %q 的数量非正", u.ID)
164			}
165			if _, err := time.Parse(time.RFC3339, u.Time); err != nil {
166				return fmt.Errorf("用量 %q 的时间不是 RFC3339: %w", u.ID, err)
167			}
168		}
169		for key, b := range s.Bills {
170			if b == nil {
171				return fmt.Errorf("账单 %q 的数据为空", key)
172			}
173			if billKey(b.CustomerID, b.Month) != key {
174				return fmt.Errorf("账单键不一致: 键 %q / 客户月份 %s|%s", key, b.CustomerID, b.Month)
175			}
176			if _, ok := s.Customers[b.CustomerID]; !ok {
177				return fmt.Errorf("账单 %q 引用了不存在的客户 %q", key, b.CustomerID)
178			}
179			if !validMonth(b.Month) {
180				return fmt.Errorf("账单 %q 的月份无效", key)
181			}
182			if len(b.Lines) == 0 {
183				return fmt.Errorf("账单 %q 没有明细", key)
184			}
185			var qty, fee int64
186			for _, ln := range b.Lines {
187				u, ok := s.Usage[ln.UsageID]
188				if !ok {
189					return fmt.Errorf("账单 %q 引用了不存在的用量 %q", key, ln.UsageID)
190				}
191				if u.CustomerID != b.CustomerID || u.Time != ln.Time || u.Quantity != ln.Quantity {
192					return fmt.Errorf("账单 %q 的明细 %q 与用量记录不一致", key, ln.UsageID)
193				}
194				if !inMonth(u.Time, b.Month) {
195					return fmt.Errorf("账单 %q 的明细 %q 不在账期内", key, ln.UsageID)
196				}
197				var err error
198				qty, err = add64(qty, ln.Quantity)
199				if err != nil {
200					return fmt.Errorf("账单 %q 汇总数量溢出", key)
201				}
202				fee, err = add64(fee, ln.LineFee)
203				if err != nil {
204					return fmt.Errorf("账单 %q 汇总金额溢出", key)
205				}
206			}
207			if qty != b.TotalQty {
208				return fmt.Errorf("账单 %q 总数量与明细不符", key)
209			}
210			if fee != b.TotalFee {
211				return fmt.Errorf("账单 %q 总金额与明细不符", key)
212			}
213			c := s.Customers[b.CustomerID]
214			for _, ln := range b.Lines {
215				lf, err := mul64(ln.Quantity, c.Price)
